sys_ui_action.script:
/**
 * Client half of the one-job-at-a-time guard. Onclick: startPreviewDiscoveryFilterMode()
 *
 * Same shape as the twin in "Preview Workload Deletion": in the Script field rather than in
 * client_script_v2, because that field is an empty stub on every UI Action in this application
 * and nothing reads it. Both halves share this field, which is why the server half below is
 * behind a `typeof window` guard.
 *
 * Purely to save a round trip that would end in an error message. The check that enforces the
 * rule runs on the server immediately before the job record is inserted, because two people
 * clicking within the same second both pass this one. Never treat this as the guard.
 *
 * GlideAjax is asynchronous, so the click always returns false and the form is submitted from
 * the callback rather than by returning true.
 */
function startPreviewDiscoveryFilterMode() {
    var check = new GlideAjax('x_illu2_illumio.IllumioUtilsAJAX');
    check.addParam('sysparm_name', 'hasRunningJob');
    // Scopes the check to the PCE Configuration this Class Mapping belongs to, so a job on a
    // different one no longer greys this out. Must match what the server half passes, or the
    // two halves disagree and the client waves through something the server then refuses.
    check.addParam('sysparm_config_sys_id', g_form.getValue('illumio_pce_configuration'));

    check.getXMLAnswer(function(answer) {
        var response;

        try {
            response = answer ? JSON.parse(answer) : { running: false };
        } catch (ex) {
            // Never leave the click doing nothing. An unreadable answer means the guard could
            // not be evaluated, and the server repeats the check anyway.
            response = { running: false };
        }

        if (response.running) {
            g_form.addErrorMessage(response.message);
            return;
        }

        gsftSubmit(null, g_form.getFormElement(), 'preview_discovery_filter_mode');
    });

    return false;
}

// Server half: a trigger, and nothing else.
//
// This used to do the whole job inside the click -- page every CMDB record the mapping would
// process, apply the exclusion filter in memory, render the CSV to a string, and write it with
// GlideSysAttachment. Capped at x_illu2_illumio.maximum_ci_records, so it was never the memory
// hazard the workload exports were; it was a scan of up to 25,000 CMDB records held open in an
// interactive transaction, which has a far shorter ceiling than a scheduled one.
//
// P0-2 point 9, the fifth and last UI Action to move. The work now lives in
// IllumioPreviewUtils.processFilterModePreview, reached through the Script Action on
// x_illu2_illumio.start_filter_mode_previe.
//
// Action name: preview_discovery_filter_mode (the client half submits it by that name).
if (typeof window === 'undefined') {
    // Declared inside the server guard for the same reason gs.include is: this Script
    // field is evaluated in the browser too, for the client half above, and IllumioLogger
    // is a server Script Include. At the top of the file it threw a ReferenceError on
    // every form load and stopped the form rendering.
    var illumioLogger = new IllumioLogger(null, 'Preview Discovery Filter Mode');

    // Inside the server guard, not at the top of the file. This Script field is evaluated in the
    // browser too, for the client half above, and `gs` does not exist there -- a top-level
    // gs.include would throw a ReferenceError and kill the onclick handler.
    gs.include("IllumioConstants");

    var mappingSysId = current.getUniqueValue();
    var tableName = current.getTableName();
    var redirectUrl = tableName + '.do?sys_id=' + mappingSysId;

    try {
        var utils = new IllumioUtils();

        if (gs.nil(current.getValue('source_table'))) {
            // Checked here rather than in the job. It costs nothing, it is the most common
            // reason this button cannot work, and telling the user now beats creating a job
            // that exists only to fail.
            gs.addErrorMessage('No source table is configured on this mapping.');
            action.setRedirectURL(redirectUrl);

        } else {
            // Scoped to the PCE Configuration this Class Mapping belongs to. It was
            // instance-wide, which was propping up two sweeps that deleted anything they did
            // not own -- both fixed, see getRunningJob.
            var runningJob = utils.getRunningJob(
                current.getValue('illumio_pce_configuration'));

            if (runningJob) {
                // The authoritative check. The client half ran the same one before submitting,
                // but that was a different transaction and anything could have started since.
                //
                // The refusal gets a job record of its own, inserted already failed so it never
                // counts as running. There is nowhere else to log it, and without it a user
                // reporting "the button does nothing" leaves no trace to look at.
                var message = utils.describeRunningJob(runningJob);

                var refusedGr = new GlideRecordSecure(TABLE_SCHEDULED_JOBS);
                refusedGr.initialize();
                refusedGr.job_owner = gs.getUser().getID();
                refusedGr.job_type = 'preview';
                refusedGr.job_status = 'failed';
                refusedGr.job_started = new GlideDateTime();
                refusedGr.job_completed = new GlideDateTime();
                refusedGr.current_operation = 'Preview refused';
                refusedGr.illumio_pce_configuration =
                    current.getValue('illumio_pce_configuration');
                refusedGr.logs = 'Discovery filter mode preview requested for source table "' +
                    current.getValue('source_table') + '" and refused. ' + message;
                refusedGr.insert();

                gs.addErrorMessage(message);
                action.setRedirectURL(redirectUrl);

            } else {
                var jobGr = new GlideRecordSecure(TABLE_SCHEDULED_JOBS);
                jobGr.initialize();
                jobGr.job_owner = gs.getUser().getID();
                jobGr.job_type = 'preview';
                jobGr.job_status = 'running';
                jobGr.job_started = new GlideDateTime();
                jobGr.current_operation = 'Preparing preview';
                jobGr.illumio_pce_configuration =
                    current.getValue('illumio_pce_configuration');
                jobGr.logs = 'Discovery filter mode preview requested for source table "' +
                    current.getValue('source_table') + '".';
                var jobSysId = jobGr.insert();
                // From here on the job record exists, so anything this action logs -- including
                // an exception out of the block below -- lands under the same job id the
                // scheduler half will use.
                illumioLogger.setContext(jobSysId);

                if (gs.nil(jobSysId)) {
                    gs.addErrorMessage('Failed to create the scheduled job for this preview.');
                } else {
                    // parm2 carries what the job record cannot: the scheduled jobs table has a
                    // PCE Configuration reference but no generic target, and this preview
                    // attaches to the Config Class Mapping rather than to the configuration.
                    var context = JSON.stringify({
                        type: new IllumioPreviewUtils().TYPE_FILTER_MODE,
                        table: tableName,
                        sysId: mappingSysId
                    });

                    gs.eventQueueScheduled('x_illu2_illumio.start_filter_mode_previe',
                        jobGr, jobSysId, context, new GlideDateTime());

                    gs.addInfoMessage('Discovery preview job started. The CSV will be attached ' +
                        'to this record when it completes. Track progress in Scheduled Jobs.');
                }

                action.setRedirectURL(redirectUrl);
            }
        }
    } catch (ex) {
        illumioLogger.error('Exception: ' + ex);
        gs.addErrorMessage('Error starting the discovery preview: ' + ex);
        action.setRedirectURL(redirectUrl);
    }
}
